[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>DeployCloud Blog — Discover the latest in web development</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
    <style>
        *, *::before, *::after {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        :root {
            --primary-dark: #171717;
            --accent-blue: #0072F5;
            --accent-blue-hover: #0062CC;
            --background-light: #FAFAFA;
            --background-white: #FFFFFF;
            --gray-50: #F9FAFB;
            --gray-100: #F3F4F6;
            --gray-200: #E5E7EB;
            --gray-300: #D1D5DB;
            --gray-400: #9CA3AF;
            --gray-500: #6B7280;
            --gray-600: #4B5563;
            --gray-700: #374151;
            --gray-800: #1F2937;
            --gray-900: #111827;
            --text-primary: #171717;
            --text-secondary: #6B7280;
            --text-tertiary: #9CA3AF;
            --border-color: #E5E7EB;
            --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
            --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
            --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
            --radius-sm: 6px;
            --radius-md: 8px;
            --radius-lg: 12px;
            --radius-full: 9999px;
            --transition-fast: 150ms ease;
            --transition-normal: 200ms ease;
            --transition-slow: 300ms ease;
        }

        html {
            font-size: 16px;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }

        body {
            font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            background-color: var(--background-light);
            color: var(--text-primary);
            line-height: 1.6;
            min-height: 100vh;
        }

        a {
            color: inherit;
            text-decoration: none;
        }

        button {
            font-family: inherit;
            cursor: pointer;
            border: none;
            background: none;
        }

        img {
            max-width: 100%;
            height: auto;
        }

        .container {
            max-width: 1280px;
            margin: 0 auto;
            padding: 0 24px;
        }

        /* Header */
        .header {
            background: var(--background-white);
            border-bottom: 1px solid var(--border-color);
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .header-inner {
            display: flex;
            align-items: center;
            justify-content: space-between;
            height: 64px;
        }

        .header-left {
            display: flex;
            align-items: center;
            gap: 40px;
        }

        .logo {
            font-size: 20px;
            font-weight: 700;
            color: var(--primary-dark);
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .logo-icon {
            width: 28px;
            height: 28px;
            background: var(--accent-blue);
            border-radius: 6px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .logo-icon svg {
            width: 18px;
            height: 18px;
            color: white;
        }

        .nav {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .nav-item {
            position: relative;
        }

        .nav-link {
            display: flex;
            align-items: center;
            gap: 4px;
            padding: 8px 12px;
            font-size: 14px;
            font-weight: 500;
            color: var(--gray-600);
            border-radius: var(--radius-sm);
            transition: all var(--transition-fast);
        }

        .nav-link:hover {
            color: var(--text-primary);
            background: var(--gray-100);
        }

        .nav-link svg {
            width: 16px;
            height: 16px;
            transition: transform var(--transition-fast);
        }

        .nav-item:hover .nav-link svg {
            transform: rotate(180deg);
        }

        .header-right {
            display: flex;
            align-items: center;
            gap: 12px;
        }

        .header-actions {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .btn-ghost {
            padding: 8px 16px;
            font-size: 14px;
            font-weight: 500;
            color: var(--gray-700);
            border-radius: var(--radius-sm);
            transition: all var(--transition-fast);
        }

        .btn-ghost:hover {
            background: var(--gray-100);
            color: var(--text-primary);
        }

        .btn-primary {
            padding: 8px 16px;
            font-size: 14px;
            font-weight: 600;
            color: white;
            background: var(--accent-blue);
            border-radius: var(--radius-sm);
            transition: all var(--transition-fast);
        }

        .btn-primary:hover {
            background: var(--accent-blue-hover);
        }

        /* Mega Menu */
        .mega-menu {
            position: absolute;
            top: 100%;
            left: 50%;
            transform: translateX(-50%);
            padding-top: 8px;
            opacity: 0;
            visibility: hidden;
            transition: all var(--transition-normal);
        }

        .nav-item:hover .mega-menu,
        .mega-menu:hover {
            opacity: 1;
            visibility: visible;
        }

        .mega-menu-content {
            background: var(--background-white);
            border: 1px solid var(--border-color);
            border-radius: var(--radius-lg);
            box-shadow: var(--shadow-lg);
            padding: 24px;
            min-width: 600px;
        }

        .mega-menu-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
        }

        .mega-menu-section h4 {
            font-size: 12px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--gray-500);
            margin-bottom: 12px;
        }

        .mega-menu-list {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 8px;
        }

        .mega-menu-list a {
            display: flex;
            align-items: flex-start;
            gap: 10px;
            padding: 6px 0;
            font-size: 14px;
            color: var(--gray-700);
            transition: color var(--transition-fast);
        }

        .mega-menu-list a:hover {
            color: var(--accent-blue);
        }

        .mega-menu-list .item-icon {
            width: 20px;
            height: 20px;
            flex-shrink: 0;
            margin-top: 2px;
            color: var(--gray-400);
        }

        .mega-menu-list .item-title {
            font-weight: 500;
            color: var(--text-primary);
        }

        .mega-menu-list .item-desc {
            font-size: 12px;
            color: var(--gray-500);
            margin-top: 2px;
        }

        /* Resources Dropdown */
        .dropdown-menu {
            position: absolute;
            top: 100%;
            left: 0;
            padding-top: 8px;
            opacity: 0;
            visibility: hidden;
            transition: all var(--transition-normal);
            min-width: 200px;
        }

        .nav-item:hover .dropdown-menu {
            opacity: 1;
            visibility: visible;
        }

        .dropdown-content {
            background: var(--background-white);
            border: 1px solid var(--border-color);
            border-radius: var(--radius-lg);
            box-shadow: var(--shadow-lg);
            padding: 8px;
        }

        .dropdown-section {
            padding: 8px 0;
        }

        .dropdown-section:not(:last-child) {
            border-bottom: 1px solid var(--border-color);
        }

        .dropdown-section h4 {
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--gray-500);
            padding: 0 12px 8px;
        }

        .dropdown-list {
            list-style: none;
        }

        .dropdown-list a {
            display: flex;
            align-items: center;
            gap: 8px;
            padding: 8px 12px;
            font-size: 14px;
            color: var(--gray-700);
            border-radius: var(--radius-sm);
            transition: all var(--transition-fast);
        }

        .dropdown-list a:hover {
            background: var(--gray-100);
            color: var(--text-primary);
        }

        .dropdown-list svg {
            width: 16px;
            height: 16px;
            color: var(--gray-400);
        }

        /* Mobile menu toggle */
        .mobile-menu-toggle {
            display: none;
            padding: 8px;
            border-radius: var(--radius-sm);
        }

        .mobile-menu-toggle svg {
            width: 24px;
            height: 24px;
            color: var(--gray-600);
        }

        /* Hero Section */
        .hero {
            padding: 48px 0;
            background: var(--background-white);
            border-bottom: 1px solid var(--border-color);
        }

        .hero-content {
            max-width: 680px;
        }

        .hero h1 {
            font-size: 40px;
            font-weight: 700;
            line-height: 1.2;
            color: var(--text-primary);
            margin-bottom: 16px;
        }

        .hero p {
            font-size: 18px;
            color: var(--text-secondary);
            line-height: 1.6;
        }

        /* Category Filters */
        .filters-section {
            padding: 24px 0;
            background: var(--background-white);
            border-bottom: 1px solid var(--border-color);
            position: sticky;
            top: 64px;
            z-index: 90;
        }

        .filters-inner {
            display: flex;
            align-items: center;
            gap: 24px;
            flex-wrap: wrap;
        }

        .category-filters {
            display: flex;
            align-items: center;
            gap: 8px;
            flex-wrap: wrap;
            flex: 1;
        }

        .filter-pill {
            padding: 8px 16px;
            font-size: 14px;
            font-weight: 500;
            color: var(--gray-600);
            background: var(--gray-100);
            border-radius: var(--radius-full);
            transition: all var(--transition-fast);
            white-space: nowrap;
        }

        .filter-pill:hover {
            background: var(--gray-200);
            color: var(--text-primary);
        }

        .filter-pill.active {
            background: var(--primary-dark);
            color: white;
        }

        .search-box {
            position: relative;
            flex-shrink: 0;
        }

        .search-box svg {
            position: absolute;
            left: 12px;
            top: 50%;
            transform: translateY(-50%);
            width: 18px;
            height: 18px;
            color: var(--gray-400);
        }

        .search-input {
            width: 240px;
            padding: 10px 12px 10px 40px;
            font-size: 14px;
            border: 1px solid var(--border-color);
            border-radius: var(--radius-full);
            background: var(--gray-50);
            transition: all var(--transition-fast);
        }

        .search-input:focus {
            outline: none;
            border-color: var(--accent-blue);
            background: var(--background-white);
            box-shadow: 0 0 0 3px rgba(0, 114, 245, 0.1);
        }

        .search-input::placeholder {
            color: var(--gray-400);
        }

        /* Featured Articles */
        .featured-section {
            padding: 48px 0;
        }

        .section-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 32px;
        }

        .section-title {
            font-size: 24px;
            font-weight: 700;
            color: var(--text-primary);
        }

        .featured-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
        }

        .featured-card {
            background: var(--background-white);
            border: 1px solid var(--border-color);
            border-radius: var(--radius-lg);
            overflow: hidden;
            transition: all var(--transition-normal);
            display: flex;
            flex-direction: column;
        }

        .featured-card:hover {
            border-color: var(--gray-300);
            box-shadow: var(--shadow-md);
            transform: translateY(-2px);
        }

        .featured-card-image {
            height: 180px;
            background: linear-gradient(135deg, var(--gray-100) 0%, var(--gray-200) 100%);
            position: relative;
            overflow: hidden;
        }

        .featured-card:nth-child(2) .featured-card-image {
            background: linear-gradient(135deg, #E0F2FE 0%, #BAE6FD 100%);
        }

        .featured-card:nth-child(3) .featured-card-image {
            background: linear-gradient(135deg, #FEF3C7 0%, #FDE68A 100%);
        }

        .featured-card-image svg {
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            width: 48px;
            height: 48px;
            color: var(--gray-400);
        }

        .featured-card-content {
            padding: 24px;
            flex: 1;
            display: flex;
            flex-direction: column;
        }

        .featured-card-meta {
            display: flex;
            align-items: center;
            gap: 12px;
            margin-bottom: 12px;
        }

        .category-tag {
            display: inline-flex;
            align-items: center;
            padding: 4px 10px;
            font-size: 12px;
            font-weight: 600;
            color: var(--accent-blue);
            background: rgba(0, 114, 245, 0.1);
            border-radius: var(--radius-full);
        }

        .post-date {
            font-size: 13px;
            color: var(--text-tertiary);
        }

        .featured-card h3 {
            font-size: 20px;
            font-weight: 700;
            line-height: 1.3;
            color: var(--text-primary);
            margin-bottom: 12px;
        }

        .featured-card p {
            font-size: 15px;
            color: var(--text-secondary);
            line-height: 1.6;
            flex: 1;
        }

        .featured-card-author {
            display: flex;
            align-items: center;
            gap: 10px;
            margin-top: 20px;
            padding-top: 20px;
            border-top: 1px solid var(--border-color);
        }

        .author-avatar {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            background: var(--gray-200);
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 14px;
            font-weight: 600;
            color: var(--gray-600);
        }

        .author-name {
            font-size: 14px;
            font-weight: 500;
            color: var(--text-primary);
        }

        /* Agentic Stats Banner */
        .stats-banner {
            background: var(--primary-dark);
            border-radius: var(--radius-lg);
            padding: 32px;
            margin-bottom: 32px;
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 24px;
        }

        .stat-item {
            text-align: center;
        }

        .stat-value {
            font-size: 32px;
            font-weight: 700;
            color: white;
            margin-bottom: 4px;
        }

        .stat-label {
            font-size: 14px;
            color: var(--gray-400);
        }

        /* Latest News */
        .latest-section {
            padding: 0 0 64px;
        }

        .latest-grid {
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 24px;
        }

        .post-card {
            background: var(--background-white);
            border: 1px solid var(--border-color);
            border-radius: var(--radius-lg);
            padding: 24px;
            transition: all var(--transition-normal);
            display: flex;
            flex-direction: column;
        }

        .post-card:hover {
            border-color: var(--gray-300);
            box-shadow: var(--shadow-sm);
        }

        .post-card.hidden {
            display: none;
        }

        .post-card-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            margin-bottom: 12px;
        }

        .post-card-meta {
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .post-card .category-tag {
            font-size: 11px;
            padding: 3px 8px;
        }

        .post-card-date {
            font-size: 12px;
            color: var(--text-tertiary);
        }

        .post-card h3 {
            font-size: 17px;
            font-weight: 600;
            line-height: 1.4;
            color: var(--text-primary);
            margin-bottom: 8px;
        }

        .post-card-excerpt {
            font-size: 14px;
            color: var(--text-secondary);
            line-height: 1.6;
            flex: 1;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
        }

        .post-card-author {
            display: flex;
            align-items: center;
            gap: 8px;
            margin-top: 16px;
        }

        .post-card .author-avatar {
            width: 28px;
            height: 28px;
            font-size: 11px;
        }

        .post-card .author-name {
            font-size: 13px;
        }

        /* No Results State */
        .no-results {
            display: none;
            text-align: center;
            padding: 64px 24px;
            grid-column: 1 / -1;
        }

        .no-results.visible {
            display: block;
        }

        .no-results svg {
            width: 64px;
            height: 64px;
            color: var(--gray-300);
            margin-bottom: 16px;
        }

        .no-results h3 {
            font-size: 18px;
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 8px;
        }

        .no-results p {
            font-size: 14px;
            color: var(--text-secondary);
        }

        /* Show More Button */
        .show-more-container {
            text-align: center;
            margin-top: 40px;
        }

        .btn-show-more {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 12px 24px;
            font-size: 15px;
            font-weight: 500;
            color: var(--text-primary);
            background: var(--background-white);
            border: 1px solid var(--border-color);
            border-radius: var(--radius-md);
            transition: all var(--transition-fast);
        }

        .btn-show-more:hover {
            background: var(--gray-50);
            border-color: var(--gray-300);
        }

        .btn-show-more svg {
            width: 18px;
            height: 18px;
        }

        .btn-show-more.hidden {
            display: none;
        }

        /* CTA Banner */
        .cta-section {
            background: var(--background-white);
            border-top: 1px solid var(--border-color);
            border-bottom: 1px solid var(--border-color);
            padding: 64px 0;
        }

        .cta-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 48px;
            align-items: center;
        }

        .cta-content h2 {
            font-size: 32px;
            font-weight: 700;
            line-height: 1.3;
            color: var(--text-primary);
            margin-bottom: 16px;
        }

        .cta-content p {
            font-size: 16px;
            color: var(--text-secondary);
            margin-bottom: 24px;
        }

        .cta-buttons {
            display: flex;
            gap: 12px;
        }

        .btn-cta-primary {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 12px 24px;
            font-size: 15px;
            font-weight: 600;
            color: white;
            background: var(--accent-blue);
            border-radius: var(--radius-md);
            transition: all var(--transition-fast);
        }

        .btn-cta-primary:hover {
            background: var(--accent-blue-hover);
        }

        .btn-cta-secondary {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 12px 24px;
            font-size: 15px;
            font-weight: 600;
            color: var(--text-primary);
            background: var(--gray-100);
            border-radius: var(--radius-md);
            transition: all var(--transition-fast);
        }

        .btn-cta-secondary:hover {
            background: var(--gray-200);
        }

        .cta-enterprise {
            background: var(--gray-50);
            border: 1px solid var(--border-color);
            border-radius: var(--radius-lg);
            padding: 32px;
        }

        .cta-enterprise h3 {
            font-size: 18px;
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 8px;
        }

        .cta-enterprise p {
            font-size: 14px;
            color: var(--text-secondary);
            margin-bottom: 20px;
        }

        .btn-cta-outline {
            display: inline-flex;
            align-items: center;
            gap: 8px;
            padding: 10px 20px;
            font-size: 14px;
            font-weight: 600;
            color: var(--text-primary);
            background: var(--background-white);
            border: 1px solid var(--border-color);
            border-radius: var(--radius-md);
            transition: all var(--transition-fast);
        }

        .btn-cta-outline:hover {
            background: var(--gray-50);
            border-color: var(--gray-300);
        }

        /* Footer */
        .footer {
            background: var(--background-white);
            padding: 64px 0 32px;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: 2fr repeat(6, 1fr);
            gap: 48px;
            padding-bottom: 48px;
            border-bottom: 1px solid var(--border-color);
        }

        .footer-brand {
            max-width: 280px;
        }

        .footer-brand .logo {
            margin-bottom: 16px;
        }

        .footer-brand p {
            font-size: 14px;
            color: var(--text-secondary);
            line-height: 1.6;
        }

        .footer-column h4 {
            font-size: 13px;
            font-weight: 600;
            color: var(--text-primary);
            margin-bottom: 16px;
        }

        .footer-column ul {
            list-style: none;
            display: flex;
            flex-direction: column;
            gap: 10px;
        }

        .footer-column a {
            font-size: 14px;
            color: var(--text-secondary);
            transition: color var(--transition-fast);
        }

        .footer-column a:hover {
            color: var(--text-primary);
        }

        .footer-bottom {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding-top: 32px;
        }

        .footer-bottom-left {
            display: flex;
            align-items: center;
            gap: 24px;
        }

        .footer-bottom-left p {
            font-size: 13px;
            color: var(--text-tertiary);
        }

        .footer-status {
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: 13px;
            color: #16A34A;
        }

        .footer-status::before {
            content: '';
            width: 8px;
            height: 8px;
            background: #16A34A;
            border-radius: 50%;
        }

        .footer-social {
            display: flex;
            align-items: center;
            gap: 16px;
        }

        .footer-social a {
            color: var(--gray-400);
            transition: color var(--transition-fast);
        }

        .footer-social a:hover {
            color: var(--gray-600);
        }

