        // State
        let currentCategory = 'all';
        let searchQuery = '';
        let visiblePostCount = 8;

        // DOM Elements
        const featuredGrid = document.getElementById('featuredGrid');
        const latestGrid = document.getElementById('latestGrid');
        const noResults = document.getElementById('noResults');
        const showMoreBtn = document.getElementById('showMoreBtn');
        const searchInput = document.getElementById('searchInput');
        const categoryFilters = document.getElementById('categoryFilters');

        // Render Functions
        function renderFeaturedCards() {
            featuredGrid.innerHTML = featuredArticles.map(article => `
                <article class="featured-card">
                    <div class="featured-card-image" style="background: ${article.gradient}">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
                            <path d="M12 2L2 7l10 5 10-5-10-5z"/>
                            <path d="M2 17l10 5 10-5"/>
                            <path d="M2 12l10 5 10-5"/>
                        </svg>
                    </div>
                    <div class="featured-card-content">
                        <div class="featured-card-meta">
                            <span class="category-tag">${article.category}</span>
                            <span class="post-date">${article.date}</span>
                        </div>
                        <h3>${article.title}</h3>
                        <p>${article.excerpt}</p>
                        <div class="featured-card-author">
                            <div class="author-avatar">${article.initials}</div>
                            <span class="author-name">By ${article.author}</span>
                        </div>
                    </div>
                </article>
            `).join('');
        }

        function renderPosts() {
            const filteredPosts = allPosts.filter(post => {
                const matchesCategory = currentCategory === 'all' || post.categorySlug === currentCategory;
                const matchesSearch = searchQuery === '' ||
                    post.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                    post.excerpt.toLowerCase().includes(searchQuery.toLowerCase()) ||
                    post.author.toLowerCase().includes(searchQuery.toLowerCase());
                return matchesCategory && matchesSearch;
            });

            if (filteredPosts.length === 0) {
                latestGrid.innerHTML = '';
                noResults.classList.add('visible');
                showMoreBtn.classList.add('hidden');
            } else {
                noResults.classList.remove('visible');
                const postsToShow = filteredPosts.slice(0, visiblePostCount);
                latestGrid.innerHTML = postsToShow.map(post => `
                    <article class="post-card">
                        <div class="post-card-header">
                            <div class="post-card-meta">
                                <span class="category-tag">${post.category}</span>
                                <span class="post-card-date">${post.date}</span>
                            </div>
                        </div>
                        <h3>${post.title}</h3>
                        <p class="post-card-excerpt">${post.excerpt}</p>
                        <div class="post-card-author">
                            <div class="author-avatar">${post.initials}</div>
                            <span class="author-name">${post.author}</span>
                        </div>
                    </article>
                `).join('') + `
                    <div class="no-results" id="noResultsInner">
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
                            <circle cx="11" cy="11" r="8"/>
                            <path d="M21 21l-4.35-4.35"/>
                            <path d="M8 8l6 6M14 8l-6 6"/>
                        </svg>
                        <h3>No results found at this time</h3>
                        <p>Try again with a different keyword.</p>
                    </div>
                `;

                // Show/hide no results inner
                const noResultsInner = document.getElementById('noResultsInner');
                if (noResultsInner) {
                    noResultsInner.style.display = filteredPosts.length === 0 ? 'block' : 'none';
                }

                // Show more button visibility
                if (filteredPosts.length <= visiblePostCount) {
                    showMoreBtn.classList.add('hidden');
                } else {
                    showMoreBtn.classList.remove('hidden');
                }
            }
        }

        // Stats Banner (injected into first featured card context)
        function getStatsBannerHTML() {
            return `
                <div class="stats-banner">
                    <div class="stat-item">
                        <div class="stat-value">30%</div>
                        <div class="stat-label">of deployments initiated by coding agents</div>
                    </div>
