                        <div class="stat-label">increase from six months ago</div>
                    </div>
                    <div class="stat-item">
                        <div class="stat-value">20×</div>
                        <div class="stat-label">more likely to call AI inference</div>
                    </div>
                    <div class="stat-item">
                        <div class="stat-value">2×</div>
                        <div class="stat-label">weekly deployments in 3 months</div>
                    </div>
                </div>
            `;
        }

        // Insert stats banner after first featured card
        function insertStatsBanner() {
            const firstCard = featuredGrid.querySelector('.featured-card');
            if (firstCard) {
                const tempDiv = document.createElement('div');
                tempDiv.innerHTML = getStatsBannerHTML();
                firstCard.insertAdjacentElement('afterend', tempDiv.firstElementChild);
            }
        }

        // Event Listeners
        categoryFilters.addEventListener('click', (e) => {
            if (e.target.classList.contains('filter-pill')) {
                // Update active state
                categoryFilters.querySelectorAll('.filter-pill').forEach(pill => {
                    pill.classList.remove('active');
                });
                e.target.classList.add('active');

                // Update filter
                currentCategory = e.target.dataset.category;
                visiblePostCount = 8;
                renderPosts();
            }
        });

        searchInput.addEventListener('input', (e) => {
            searchQuery = e.target.value.trim();
            visiblePostCount = 8;
            renderPosts();
        });

        showMoreBtn.addEventListener('click', () => {
            visiblePostCount += 4;
            renderPosts();
        });

        // Initialize
        renderFeaturedCards();
        renderPosts();
        insertStatsBanner();
    </script>
